SELECT *
  FROM Employees
 WHERE REGEXP_LIKE(FIRST_NAME, '^A.*Y$');

SELECT *
  FROM Employees
 WHERE REGEXP_LIKE(FIRST_NAME, '^A.*Y$', 'i');

SELECT *
  FROM Products
 WHERE REGEXP_LIKE(PRODUCT_NAME, '[AEIOU]{3,}');

DROP TABLE IF EXISTS Employees;
CREATE TABLE Employees (ID INT IDENTITY(101, 1),
                        [Name] VARCHAR(150),
                        Email VARCHAR(320)
                            CHECK (REGEXP_LIKE(Email, '^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$')),
                        Phone_Number NVARCHAR(20) CHECK (REGEXP_LIKE(Phone_Number, '^(\d{3})-(\d{3})-(\d{4})$')));

SELECT REGEXP_REPLACE(PRODUCT_NAME, '[ae]', 'X', 1, 0, 'i')
  FROM PRODUCTS;

SELECT REGEXP_REPLACE(PRODUCT_DESCRIPTION, 'cat|dog', 'pet', 1, 1, 'i')
  FROM PRODUCTS;

SELECT REGEXP_REPLACE(PHONE_NUMBER, '\d{4}$', '****')
  FROM CUSTOMERS;

SELECT REGEXP_SUBSTR(EMAIL, '@(.+)$', 1, 1, 'i', 1) AS DOMAIN
  FROM CUSTOMERS;

SELECT REGEXP_SUBSTR(COMMENT, '\b[aeiou]\w*', 1, 1, 'i') AS WORD
  FROM FEEDBACK;

SELECT REGEXP_SUBSTR(CARD_NUMBER, '\d{4}$') AS LAST_FOUR
  FROM PAYMENTS;

SELECT PRODUCT_NAME,
       REGEXP_COUNT(PRODUCT_NAME, 'a') AS A_COUNT
  FROM PRODUCTS;

SELECT COUNT(*)
  FROM PRODUCTS
 WHERE REGEXP_COUNT(PRODUCT_NAME, 'ing$') > 0;

SELECT COUNT(*)
  FROM PRODUCTS
 WHERE REGEXP_COUNT(PRODUCT_NAME, '[^aeiou]{3}', 1, 'i') > 0;

SELECT REGEXP_INSTR(PRODUCT_DESCRIPTION, '\d+')
  FROM PRODUCTS;

SELECT REGEXP_INSTR(PRODUCT_NAME, 'a', 1, 3, 0, 'i')
  FROM PRODUCTS;

SELECT REGEXP_INSTR(PRODUCT_DESCRIPTION, 't.*?e', 1, 1, 1)
  FROM PRODUCTS;
